// ============================================================
// ESTRATEGIA: Cruce de Medias Móviles Simples (SMA 7 vs SMA 21)
// ============================================================
// Entrada: array de klines de Binance
// Formato kline: [openTime, open, high, low, close, volume, closeTime, ...]
// ============================================================

try {
  const items = $input.all();

  // 1) Validar que tenemos datos
  if (!items || items.length === 0) {
    throw new Error('No se recibieron datos desde Binance');
  }

  // 2) Extraer el array de klines (el primer item contiene el array completo)
  let klines = items[0].json;
  if (!Array.isArray(klines)) {
    // A veces viene envuelto en { data: [...] }
    klines = klines.data || klines.body || klines;
  }
  if (!Array.isArray(klines) || klines.length < 21) {
    throw new Error(`Datos insuficientes: ${klines ? klines.length : 0} velas`);
  }

  // 3) Convertir precios de cierre a número
  const closes = klines.map(k => parseFloat(k[4]));
  const precioActual = closes[closes.length - 1];

  // 4) Función SMA
  const sma = (arr, period) => {
    if (arr.length < period) return null;
    const slice = arr.slice(-period);
    return slice.reduce((a, b) => a + b, 0) / period;
  };

  // 5) Calcular medias: actuales y previas (para detectar cruce)
  const smaCortaActual = sma(closes, 7);
  const smaLargaActual = sma(closes, 21);
  const smaCortaPrev   = sma(closes.slice(0, -1), 7);
  const smaLargaPrev   = sma(closes.slice(0, -1), 21);

  // 6) Determinar señal por cruce
  let señal = 'NEUTRO';
  if (smaCortaPrev !== null && smaLargaPrev !== null) {
    const cruceAlcista = smaCortaPrev <= smaLargaPrev && smaCortaActual > smaLargaActual;
    const cruceBajista = smaCortaPrev >= smaLargaPrev && smaCortaActual < smaLargaActual;

    if (cruceAlcista) señal = 'COMPRA';
    else if (cruceBajista) señal = 'VENTA';
  }

  // 7) Devolver objeto limpio
  return [{
    json: {
      activo: $env.TRADING_SYMBOL || 'BTCUSDT',
      precioActual: Number(precioActual.toFixed(2)),
      señal: señal,
      smaCorta: Number(smaCortaActual.toFixed(2)),
      smaLarga: Number(smaLargaActual.toFixed(2)),
      timestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  // En caso de error, devolvemos una señal NEUTRA con el error embebido
  // para que el flujo continúe y el Error Trigger pueda alertar si se desea.
  return [{
    json: {
      activo: $env.TRADING_SYMBOL || 'BTCUSDT',
      precioActual: 0,
      señal: 'NEUTRO',
      error: error.message,
      timestamp: new Date().toISOString()
    }
  }];
}

